import { describe, it } from 'vitest';
import { parse } from '../src/parse';
import { nextRung } from '../src/select-all-ladder';
import { coveredForestOf, subtreeCoverOf, forestCoverOf, type LineRange } from '../src/escalate';
import { nodeAtLine } from '../src/locate';

const LINES = ['- P', '\t- c1', '\t- c2', '- Q'];
const doc = parse(LINES.join('\n'));
const n = (l: number) => nodeAtLine(doc, l)!;
const R = (a: [number, number], h: [number, number]): LineRange => ({
  anchor: { line: a[0], ch: a[1] }, head: { line: h[0], ch: h[1] },
});
const fmt = (r: LineRange | null) =>
  r ? `${r.anchor.line},${r.anchor.ch} -> ${r.head.line},${r.head.ch}` : 'null (fall through to native)';
const cover = (r: LineRange) => {
  const f = coveredForestOf(doc, r);
  return f ? `COVER roots=[${f.roots.map((x) => x.node.lines[0]!.trim())}]` : 'NOT A COVER';
};

describe('Mod-A over extension-built selections', () => {
  it('ladder from forward multi-root covers', () => {
    const cases: [string, LineRange][] = [
      ['[c1] alone',        { anchor: subtreeCoverOf(doc, n(1)).start, head: subtreeCoverOf(doc, n(1)).end }],
      ['[c1,c2] fwd',       { anchor: forestCoverOf(doc, n(1), n(2)).cover.start, head: forestCoverOf(doc, n(1), n(2)).cover.end }],
      ['[c1,c2,Q] fwd',     { anchor: forestCoverOf(doc, n(1), n(3)).cover.start, head: forestCoverOf(doc, n(1), n(3)).cover.end }],
      ['[c2,Q] fwd',        { anchor: forestCoverOf(doc, n(2), n(3)).cover.start, head: forestCoverOf(doc, n(2), n(3)).cover.end }],
      ['[P] (after swallow, BACKWARD)', { anchor: subtreeCoverOf(doc, n(0)).end, head: subtreeCoverOf(doc, n(0)).start }],
    ];
    for (const [label, r] of cases) {
      console.log(`  ${label.padEnd(32)} ${cover(r).padEnd(34)} Mod-A -> ${fmt(nextRung(doc, r))}`);
    }
  });

  it('is the ladder rung 1 an escalation cover?', () => {
    // fresh caret in c1, one Mod-A
    const caret = R([1, 4], [1, 4]);
    const rung1 = nextRung(doc, caret)!;
    console.log(`  Mod-A from caret in c1 -> ${fmt(rung1)}   ${cover(rung1)}`);
    const rung2 = nextRung(doc, rung1)!;
    console.log(`  Mod-A again            -> ${fmt(rung2)}   ${cover(rung2)}`);
    const rung3 = nextRung(doc, rung2)!;
    console.log(`  Mod-A again            -> ${fmt(rung3)}   ${cover(rung3)}`);
  });
});
